import { test, expect } from '@playwright/test';

test.describe('Password Confirmation Mismatch Error - Real-time Validation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/signup');
  });

  test('should display password mismatch error when confirmation password does not match', async ({ page }) => {
    // Fill in password field
    const passwordField = page.getByLabel('Password');
    await passwordField.fill('SecurePassword123');

    // Fill in confirmation password field with different value
    const confirmPasswordField = page.getByLabel('Confirm Password');
    await confirmPasswordField.fill('WrongPassword123');

    // Verify error message appears in real-time
    const errorMessage = page.getByText('Passwords and confirmation passwords do not match');
    await expect(errorMessage).toBeVisible();

    // Verify error message is associated with the confirmation password field
    await expect(confirmPasswordField).toHaveAttribute('data-error', 'true');

    // Verify signup button is disabled
    const signupButton = page.getByRole('button', { name: /Sign up/i });
    await expect(signupButton).toBeDisabled();

    // Verify form submission is prevented
    await signupButton.click();
    await expect(page).toHaveURL(/.*signup/);
  });

  test('should clear error message when confirmation password matches password', async ({ page }) => {
    // Fill in password field
    const passwordField = page.getByLabel('Password');
    await passwordField.fill('SecurePassword123');

    // Fill in confirmation password field with mismatching value
    const confirmPasswordField = page.getByLabel('Confirm Password');
    await confirmPasswordField.fill('WrongPassword123');

    // Verify error message is visible
    const errorMessage = page.getByText('Passwords and confirmation passwords do not match');
    await expect(errorMessage).toBeVisible();

    // Fill in confirmation password field with matching value
    await confirmPasswordField.fill('SecurePassword123');

    // Verify error message is cleared
    await expect(errorMessage).not.toBeVisible();

    // Verify confirmation password field no longer has error attribute
    await expect(confirmPasswordField).not.toHaveAttribute('data-error');

    // Verify signup button is enabled
    const signupButton = page.getByRole('button', { name: /Sign up/i });
    await expect(signupButton).not.toBeDisabled();

    // Verify form can be submitted
    await signupButton.click();
    await expect(page).toHaveURL(/.*success/);
  });
});
